$n=0;$ok=function($v,$label)use(&$n){if(!$v)throw new RuntimeException($label);$n++;};$reject=function(callable $call,$label)use($ok){try{$call();}catch(Illuminate\Validation\ValidationException|Illuminate\Auth\Access\AuthorizationException $e){$ok(true,$label);return;}throw new RuntimeException('Unexpected success: '.$label);};
