$vehicle=Vehicle::create(['user_id'=>$driver->id,'plate'=>'ABC-1234']);$service=new NotificationDriverService;$notificationRequest=App\Http\Requests\StoreNotificationDriverRequest::class;$r=$make($notificationRequest,['plate'=>'abc-1234','type'=>1,'driver_id'=>$other->id,'user_id'=>$admin->id,'read'=>1],$sender);$ok($r->validated()['plate']==='ABC1234','old plate format normalized');
$notice=$service->store($r->validated(),$sender);$ok($notice->driver_id===$driver->id,'recipient derives only from vehicle');$ok($notice->user_id===$sender->id,'sender cannot impersonate another user');$ok($notice->read===false,'new notice starts unread');Queue::assertPushed(SendNotificationDriverMailJob::class,1);$ok(true,'delivery queued after registration');
